'use strict';
const $=id=>document.getElementById(id);const icon=(name,cls='')=>`<i class="ph ph-${name} ${cls}" aria-hidden="true"></i>`;
const groups=[{id:'choices',name:'Device choices',icon:'sliders-horizontal'},{id:'inside',name:'Inside the device',icon:'cpu'},{id:'networks',name:'Connections',icon:'wifi-high'},{id:'security',name:'Security',icon:'shield-check'},{id:'quiz',name:'Try yourself',icon:'lightbulb'}];
const lessons=[
{id:'speed',group:'choices',name:'Speed & battery',icon:'speedometer',title:'Speed has a cost',desc:'Same sensor. Same job. Change its processor speed.',why:'This example holds the workload constant. A higher clock uses more active power in our teaching model. Finishing earlier also gives more time to sleep, so faster is not always worse or better. Architecture, I/O delays and the workload matter too.'},
{id:'battery',group:'choices',name:'Battery life',icon:'battery-high',title:'How long will it last?',desc:'Keep the battery. Change the current draw.',why:'Estimated hours = capacity in mAh ÷ average current in mA, for compatible battery and load conditions. mAh measures electric charge. Wh measures energy. Voltage, losses, temperature and ageing affect real runtime. These examples assume a fixed voltage and constant current.'},
{id:'sleep',group:'choices',name:'Sleep mode',icon:'moon',title:'Doing nothing can save a lot',desc:'A sensor only needs to check once a minute.',why:'Duty cycle is the fraction of time spent active. Average current = active current × active fraction + sleep current × sleep fraction. Here active is 20 mA, sleep is 0.02 mA, and the sleeping sensor works for 1 second each minute. Real transmit bursts and wake-up overhead would change the result.'},
{id:'size',group:'choices',name:'Form factor',icon:'resize',title:'Small changes what fits',desc:'Try a wearable or a computer on your wrist.',why:'Form factor means size, shape, weight, connectors, enclosure and mounting. A small enclosure limits battery size, cooling and ports. A larger device can accommodate more components. The illustrations show design choices, not measured product dimensions.'},
{id:'sensing',group:'choices',name:'Sense & act',icon:'plant',title:'A device that notices and acts',desc:'Dry the soil. Watch the system respond.',why:'A sensor measures the physical world. A CPU runs the decision rule. An actuator changes the physical world, such as switching a pump. Connectivity lets the device share a reading. This example uses a simple threshold; real irrigation also needs calibration and fail-safe control.'},
{id:'cpu',group:'inside',name:'CPU & cores',icon:'cpu',title:'CPU: the part that runs instructions',desc:'Give eight independent tasks to one core or four.',why:'CPU means Central Processing Unit. A core executes instructions. Multiple cores can share independent tasks, but a sequential task cannot automatically run four times faster. Clock speed counts cycles per second. One cycle does not necessarily complete one instruction. This animation uses ideal parallel scheduling, with no real timing units.'},
{id:'memory',group:'inside',name:'RAM, ROM & flash',icon:'memory',title:'What survives the power switch?',desc:'Cut the power. See which memory keeps its contents.',why:'RAM = Random Access Memory: working data, usually volatile. ROM = Read-Only Memory: fixed nonvolatile code, such as a boot routine. Flash is rewritable nonvolatile memory: often the place firmware lives. They have different roles. Saving RAM data to nonvolatile storage must happen before power is lost.'},
{id:'ram',group:'inside',name:'RAM capacity',icon:'squares-four',title:'RAM is your working space',desc:'Can twelve readings fit in eight memory slots?',why:'More RAM lets a device hold more active data or larger programs. It does not automatically increase CPU speed. The slots are a visual model, not bytes. When the buffer fills, this demo rejects new readings; real programs might drop old data, compress it, use storage or report an error.'},
{id:'io',group:'inside',name:'I/O & GPIO',icon:'arrows-left-right',title:'Inputs arrive. Outputs act.',desc:'Press a physical button. A GPIO output controls an LED.',why:'I/O means Input/Output. GPIO means General-Purpose Input/Output: configurable pins for digital signals. A GPIO output may need a resistor or driver. An ADC (Analog-to-Digital Converter) turns an analog sensor voltage into a number. Analog values and digital high/low signals are different.'},
{id:'hardware',group:'inside',name:'CPU, MCU & SBC',icon:'circuitry',title:'A core, a chip, a whole board',desc:'These names describe different levels of hardware.',why:'CPU means Central Processing Unit. MCU means Microcontroller Unit: a chip combining CPU core(s), RAM and peripherals, often with built-in flash or external program storage. SBC means Single-Board Computer: a complete board, typically an application processor/SoC, RAM, storage interfaces and I/O. SoC means System-on-Chip. An MCU is a kind of integrated system, and an SBC can use an SoC. Raspberry Pi Pico is an MCU development board; Raspberry Pi 5 is an SBC.'},
{id:'firmware',group:'inside',name:'Firmware & OS',icon:'code',title:'Software tells hardware what to do',desc:'Change the firmware. Keep the same device.',why:'Firmware is software closely tied to a device’s hardware. It is commonly stored in flash and can be updated. An OS (Operating System) manages tasks and resources. Many SBCs run Linux. MCUs can run a single loop, an RTOS, multiple tasks, or an interpreter such as MicroPython. Firmware and operating systems are not a strict either/or division.'},
{id:'connectivity',group:'networks',name:'Choose a connection',icon:'wifi-high',title:'How does the reading get there?',desc:'Choose a connection. Follow the data path.',why:'Wi-Fi normally joins a local access point. BLE (Bluetooth Low Energy) can send small readings to a phone or gateway. Zigbee uses a coordinator and can form a mesh. LoRaWAN uses LoRa radio with gateways and network servers. Cellular reaches an operator network. Ethernet is wired. Local connectivity alone does not guarantee internet access. Radio range and power depend on the hardware, settings and environment.'},
{id:'range',group:'networks',name:'Range & obstacles',icon:'broadcast',title:'The room affects the radio',desc:'Put a wall in this sensor’s Bluetooth link.',why:'Radio signals weaken with distance and obstacles. This is one illustrative short-range BLE setup; Bluetooth has no universal ten-metre limit. Antennas, transmit power, PHY, interference and receiver sensitivity all matter. A wall may weaken or block the link, depending on those conditions.'},
{id:'mesh',group:'networks',name:'Mesh & gateways',icon:'graph',title:'A relay makes another path',desc:'The direct Zigbee route is blocked. Add a powered relay.',why:'In Zigbee, router-capable powered devices can relay messages. A sleeping battery end device usually does not relay. A coordinator starts and manages the network; a gateway can bridge it to another network. Mesh is a network structure, not a promise that every device relays.'},
{id:'bandwidth',group:'networks',name:'Data rate',icon:'cell-signal-full',title:'A tiny reading or a whole video?',desc:'Send two kinds of data over LoRaWAN.',why:'Bandwidth/data rate is how much data a link can carry per second. LoRaWAN is designed for small, infrequent messages and low power over wide areas, not continuous video. Wi-Fi or Ethernet usually suit video better. LoRa is a radio modulation technology; LoRaWAN (Long Range Wide Area Network) is the networking protocol and system built around it.'},
{id:'poe',group:'networks',name:'Ethernet & PoE',icon:'plugs-connected',title:'One cable can carry two things',desc:'Connect a compatible camera with Power over Ethernet.',why:'Ethernet carries data. PoE means Power over Ethernet: compatible network equipment also supplies power on the Ethernet cable. Both the source and device must support compatible PoE. A Raspberry Pi 5 needs a separate compatible PoE+ HAT; an Ethernet port by itself does not imply PoE support. USB and UART are useful local links but are not automatically internet connections.'},
{id:'edge',group:'networks',name:'Edge & cloud',icon:'cloud',title:'Where does the decision happen?',desc:'Disconnect the internet from a smart door.',why:'Edge processing runs near the sensor. Cloud processing runs on remote servers. A local control loop can work through an internet outage if the local sensors, power and software remain available. A decision that depends on a cloud response needs connectivity or a fallback. Both approaches can coexist.'},
{id:'updates',group:'security',name:'Security updates',icon:'shield-check',title:'A fix only helps after it’s installed',desc:'This teaching camera has a known software weakness.',why:'A firmware update can patch known vulnerabilities. It does not guarantee perfect security. Devices also need appropriate authentication, secure communication, safe defaults and an update/support plan. This demo is conceptual and never connects to a real camera.'},
{id:'cls',group:'security',name:'Singapore CLS label',icon:'seal-check',title:'More stars, more assessment',desc:'Explore Singapore’s four CLS(IoT) levels.',why:'CSA administers Singapore’s Cybersecurity Labelling Scheme for IoT. Levels correspond to progressively completed assessment tiers. Higher levels include earlier tiers, but no label guarantees immunity to attacks. Verify an actual product on CSA’s list. As checked on 13 October 2026, residential routers sold in Singapore must meet Level 1 requirements; Level 2 is expected by end-2027.'},
{id:'quiz',group:'quiz',name:'Quick concept check',icon:'lightbulb',title:'Try it without the hints',desc:'Choose an answer. Get an explanation straight away.',why:'These checks test whether a student can apply a concept, not just remember a word. Ask students to predict a demo outcome, try it, then explain what changed. A score here is informal practice and is not evidence that the site improves learning. Use an exit ticket or pre/post check with your class to evaluate that.'}
];
let current='speed',state={},timers=[],explored=new Set();try{explored=new Set(JSON.parse(localStorage.getItem('iot-explored')||'[]').filter(id=>lessons.some(l=>l.id===id)))}catch{};
const lesson=()=>lessons.find(l=>l.id===current);const opts=(values,value)=>`<div class="choice-row">${values.map(([v,label,ic])=>`<button class="choice ${value===v?'selected':''}" data-action="choose" data-value="${v}" aria-pressed="${value===v}">${ic?icon(ic):''}${label}</button>`).join('')}</div>`;
const action=(a,label,ic='cursor-click')=>`<div class="action-row"><button class="primary" data-action="${a}">${icon(ic)}${label}</button></div>`;
const effect=(text,warn=false)=>`<div class="effect ${warn?'warn':''}" aria-live="polite">${icon(warn?'warning-circle':'lightbulb')}<div>${text}</div></div>`;
const stage=(body,label='CLICK TO EXPLORE')=>`<div class="stage"><div class="stage-label">${icon('flask')}${label}</div>${body}</div>`;
const meter=(title,value,width,purple=false)=>`<div><div class="metric-title"><span>${title}</span><b>${value}</b></div><div class="meter ${purple?'purple':''}"><span style="width:${width}%"></span></div></div>`;
const node=(name,ic,caption='',cls='')=>`<div class="flow-node"><div class="node-icon ${cls}">${icon(ic)}</div><h3>${name}</h3><p>${caption||'&nbsp;'}</p></div>`;
const link=(active=true,packet='data')=>`<div class="connector ${active?'active':''}">${icon('arrow-right')}<span class="packet">${packet}</span></div>`;
const asset=(name,alt,cls='')=>`<img class="hero-device ${cls}" src="assets/${name}" alt="${alt}">`;
const source=(url,label)=>`<a class="source-link" href="${url}" target="_blank" rel="noopener">${label} ${icon('arrow-up-right')}</a>`;
function init(id){const defaults={speed:{value:'slow'},battery:{value:'100'},sleep:{value:'awake'},size:{value:'wearable'},sensing:{value:'wet'},cpu:{value:'1',processed:0,busy:false},memory:{on:true},ram:{value:'8',count:0},io:{on:false},hardware:{value:'mcu'},firmware:{value:'25'},connectivity:{value:'wifi'},range:{wall:false},mesh:{relay:false},bandwidth:{value:'reading'},poe:{value:'ethernet'},edge:{value:'edge',online:true},updates:{updated:false},cls:{value:'1'},quiz:{index:0,answer:null,score:0}};state={...defaults[id]}}
function mark(){explored.add(current);try{localStorage.setItem('iot-explored',JSON.stringify([...explored]))}catch{}updateProgress();renderSidebar()}
function updateProgress(){$('progress-text').textContent=`${explored.size} / ${lessons.length} explored`;$('progress-fill').style.width=explored.size/lessons.length*100+'%'}
function renderSidebar(){const g=lesson().group;const ls=lessons.filter(l=>l.group===g);$('group-label').textContent=groups.find(x=>x.id===g).name.toUpperCase();$('group-count').textContent=ls.length+' demos';$('categories').innerHTML=groups.map(x=>`<button class="category ${x.id===g?'active':''}" data-group="${x.id}" aria-pressed="${x.id===g}">${icon(x.icon)}${x.name}</button>`).join('');$('lessons').innerHTML=ls.map(l=>`<button class="lesson-link ${l.id===current?'active':''}" data-lesson="${l.id}" ${l.id===current?'aria-current="page"':''}>${icon(l.icon)}<span>${l.name}</span>${explored.has(l.id)?icon('check','visited'):''}</button>`).join('')}
function navigate(id){if(!lessons.some(l=>l.id===id))id='speed';timers.forEach(clearInterval);timers=[];current=id;init(id);renderSidebar();const l=lesson();$('lesson-kicker').textContent=groups.find(g=>g.id===l.group).name.toUpperCase()+' / '+String(lessons.indexOf(l)+1).padStart(2,'0');$('lesson-title').textContent=l.title;$('lesson-description').textContent=l.desc;$('why-content').textContent=l.why;$('why').open=false;$('lesson-position').textContent=String(lessons.indexOf(l)+1).padStart(2,'0')+' / '+lessons.length+' experiments';$('next').innerHTML=lessons.indexOf(l)===lessons.length-1?'Back to first demo '+icon('arrow-right'):'Next experiment '+icon('arrow-right');draw();history.replaceState(null,'','#'+id)}
function draw(){let html='';const v=state.value;
if(current==='speed'){const fast=v==='fast';html=stage(`<div class="display-pair">${asset('wearable.png','Illustrated wearable sensor cutaway')}<div class="metrics"><div><div class="big-label">${fast?'96':'24'} <span class="small-label">MHz</span></div><div class="small-label">Same microcontroller</div></div>${meter('Task finishes in',fast?'1 ms':'4 ms',fast?20:80)}${meter('Active power',fast?'300 mW':'20 mW',fast?90:24,true)}${meter('Battery lasts',fast?'138 days':'149 days',fast?75:85)}</div></div>${opts([['slow','Slow','leaf'],['fast','Fast','lightning']],v)}<p class="note-small">Illustrative model · one tiny task per second · 10 Wh battery</p>`)+effect(fast?'Finishes sooner. Uses more active power. <strong>Less battery life in this example.</strong>':'Already fast enough for one reading per second. <strong>Extra speed is optional.</strong>')}
if(current==='battery'){const ma=Number(v),hours=5000/ma;html=stage(`<div class="operation"><div>5,000<small>mAh capacity</small></div><span style="color:#a1b191">÷</span><div>${ma}<small>mA current</small></div><span style="color:#a1b191">=</span><div>${hours.toLocaleString()}<small>hours estimated</small></div></div><div class="power-meter"><span style="width:${ma===100?12:ma===10?55:100}%"></span></div><div class="map-caption">Same battery, different load</div>${opts([['100','100 mA'],['10','10 mA'],['1','1 mA']],v)}<p class="note-small">Fixed voltage. Constant average current. Real runtime varies.</p>`)+effect(`<strong>${ma===100?'50 hours':ma===10?'500 hours':'5,000 hours'}.</strong> Lower average current makes the same battery last longer.`)}
if(current==='sleep'){const asleep=v==='sleep';html=stage(`<div class="display-pair">${asset('plant.png','Illustrated smart soil moisture sensor','plant')}<div class="metrics"><div class="big-label">${asleep?'0.353':'20'} <span class="small-label">mA average</span></div>${meter('Active time',asleep?'1 / 60 seconds':'60 / 60 seconds',asleep?2:100)}${meter('Estimated runtime',asleep?'118 days':'50 hours',asleep?90:8)}<div class="small-label">1,000 mAh battery</div></div></div>${opts([['awake','Always awake','sun'],['sleep','Sleep between readings','moon']],v)}`)+effect(asleep?'Wake, measure, sleep. <strong>About 57× longer runtime in this model.</strong>':'Staying awake spends energy even when no new reading is needed.')}
if(current==='size'){const small=v==='wearable';html=stage(`<div class="display-pair">${small?asset('wearable.png','Compact wearable sensor'):asset('pi5.png','Official Raspberry Pi 5 board photo')}<div><div class="big-label">${small?'Wearable':'SBC'}</div><div class="hardware-tags">${(small?['Fits on a wrist','Small battery','Few ports']:['Larger enclosure','More ports','Cooling space']).map(t=>'<span>'+t+'</span>').join('')}</div><p class="hardware-copy" style="color:#7c8b6f;font-size:12px;line-height:1.8;margin-top:16px">${small?'Easy to carry. Less room for components.':'More capability. More space to house and cool it.'}</p></div></div>${opts([['wearable','Wearable','watch'],['board','Computer board','circuitry']],v)}<p class="note-small">Wearable: representative illustration. Board: real Raspberry Pi 5.</p>`)+effect(small?'Small devices suit the body. <strong>Space limits the design.</strong>':'An SBC suits a fixed gateway or camera enclosure. <strong>Choose size for the job.</strong>')}
if(current==='sensing'){const dry=v==='dry';html=stage(`<div class="display-pair">${asset('plant.png','Smart pot with soil sensor','plant')}<div><div class="big-label">${dry?'15':'65'}<span class="small-label">% moisture</span></div><div class="flow" style="justify-content:start;padding-bottom:0">${node('Sensor','thermometer-simple',dry?'Dry':'Moist')}${link(true,'reading')}${node('Pump','drop',dry?'ON':'OFF',dry?'':'off')}</div></div></div>${opts([['wet','Moist soil','drop'],['dry','Dry soil','sun']],v)}`)+effect(dry?'Sensor reads dry. CPU checks the rule. <strong>The pump turns on.</strong>':'Sensor reads moist. <strong>The pump stays off.</strong>')}
if(current==='cpu'){html=stage(`<div class="flow">${node('Tasks','list-checks','8 independent readings')}${link(state.busy,'job')}${node('CPU','cpu',v==='1'?'1 core':'4 cores')}${link(state.busy,'done')}${node('Result','check-circle',state.processed+' / 8 done',state.processed===8?'':'off')}</div><div class="work-queue">${Array.from({length:8},(_,i)=>`<div class="task ${i<state.processed?'done':''}">${icon(i<state.processed?'check':'file-text')}</div>`).join('')}</div>${opts([['1','1 core'],['4','4 cores']],v)}${action('process',state.busy?'Processing…':'Run the tasks','play')}<p class="note-small">Idealized independent tasks. Animation speed is not a benchmark.</p>`)+effect(state.processed===8?(v==='4'?'Four cores shared the independent tasks. <strong>A sequential job would behave differently.</strong>':'One core finished tasks one at a time.'):state.busy?'The CPU is running the instructions.':'CPU = <strong>Central Processing Unit.</strong> Each core executes instructions.')}
if(current==='memory'){html=stage(`<div class="memory-columns"><div class="memory-card">${icon('memory')}<h3>RAM</h3><div class="term">Random Access Memory</div><div class="memory-data ${state.on?'':'blank'}">${state.on?'Reading: 24.8 °C':'Cleared'}</div></div><div class="memory-card">${icon('lock-key')}<h3>ROM</h3><div class="term">Read-Only Memory</div><div class="memory-data">Boot code kept</div></div><div class="memory-card">${icon('floppy-disk')}<h3>Flash</h3><div class="term">Rewritable storage</div><div class="memory-data">Firmware kept</div></div></div>${action('power',state.on?'Cut the power':'Power on','power')}<p class="note-small">Ordinary volatile RAM. Flash and ROM retain contents without power.</p>`)+effect(state.on?'RAM holds the current reading. <strong>ROM and flash keep stored code.</strong>':'The working reading disappears from RAM. <strong>ROM and flash keep their contents.</strong>')}
if(current==='ram'){const cap=Number(v),used=Math.min(state.count,cap),full=state.count>cap;html=stage(`<div class="big-reading">${used} / ${cap}<small>slots used</small></div><div class="memory-grid">${Array.from({length:cap},(_,i)=>`<div class="memory-slot ${i<used?'filled':''}">${i<used?'24°':'·'}</div>`).join('')}</div>${opts([['8','Small RAM'],['16','More RAM']],v)}${action('readings','Load 12 readings','plus')}<p class="note-small">Slots represent working space, not actual bytes.</p>`)+effect(state.count===0?'Choose the working space, then load the readings.':full?'The buffer fills. <strong>Four readings do not fit.</strong> More RAM creates more working space.':'All twelve readings fit. <strong>More RAM holds more active data.</strong>',full)}
if(current==='io'){html=stage(`<div class="flow">${node('Button','hand-tap',state.on?'Pressed':'Released')}${link(state.on,'HIGH')}${node('MCU','cpu','Reads input')}${link(state.on,'HIGH')}${node('LED','lightbulb',state.on?'ON':'OFF',state.on?'amber':'off')}</div><div class="labels-row" style="margin:3px auto 24px"><span>INPUT</span><span>DECISION</span><span>OUTPUT</span></div>${action('press',state.on?'Release the button':'Press the button','hand-tap')}`)+effect(state.on?'The input changes. The program sets an output. <strong>The LED lights up.</strong>':'GPIO = <strong>General-Purpose Input/Output.</strong> Pins connect code to physical signals.')}
if(current==='hardware'){const data={cpu:{name:'CPU core',tag:'Central Processing Unit',parts:['CPU'],copy:'Executes instructions. It is a component inside an MCU or a larger processor.'},mcu:{name:'MCU chip',tag:'Microcontroller Unit',parts:['CPU','RAM','ROM','I/O'],copy:'CPU core(s), RAM and peripherals in one chip. Firmware storage may be on or off chip.'},sbc:{name:'SBC board',tag:'Single-Board Computer',parts:['SoC','RAM','Storage','I/O'],copy:'A complete computer board. Raspberry Pi 5 can run Linux and many programs.'}}[v];html=stage(`<div class="big-reading" style="font-size:25px">${data.name}<small>${data.tag}</small></div><div class="chip-layout"><div class="small-label">${v==='sbc'?'ONE CIRCUIT BOARD':'INSIDE THE CHIP'}</div><div class="chip-parts">${['CPU','RAM','ROM','I/O'].map((part,i)=>`<div class="chip-part ${v==='cpu'&&i!==0?'dim':v==='cpu'&&i===0?'focus':''}">${icon(['cpu','memory','floppy-disk','arrows-left-right'][i])}${data.parts[i]||part}</div>`).join('')}</div></div>${v==='cpu'?'<p class="diagram-note">CPU: the instruction engine inside a chip</p>':`<div style="display:flex;align-items:center;justify-content:center;gap:15px;margin:8px 0"><img class="mini-board" src="assets/${v==='mcu'?'rp2040.jpg':'pi5.png'}" alt="${v==='mcu'?'Official RP2040 microcontroller photograph':'Official Raspberry Pi 5 board photograph'}"><div><div class="small-label">REAL HARDWARE</div><b style="font-size:12px">${v==='mcu'?'RP2040 microcontroller':'Raspberry Pi 5 SBC'}</b><br>${source(v==='mcu'?'https://www.raspberrypi.com/products/rp2040/':'https://www.raspberrypi.com/products/raspberry-pi-5/','Raspberry Pi')}</div></div>`}${opts([['cpu','CPU'],['mcu','MCU'],['sbc','SBC']],v)}<p class="note-small">${data.copy}</p>`)+effect(v==='cpu'?'A CPU is the instruction engine. <strong>Both MCUs and SBCs contain CPU cores.</strong>':v==='mcu'?'Example: <strong>RP2040</strong> is an MCU. Raspberry Pi Pico is a board built around it.':'Example: <strong>Raspberry Pi 5</strong> is an SBC. It contains a processor, RAM and interfaces.')}
if(current==='firmware'){const cool=v==='25';html=stage(`<div class="display-pair">${asset('plant.png','Sensor illustrating a firmware controlled rule','plant')}<div class="metrics"><div class="small-label">Temperature reading</div><div class="big-label">28 <span class="small-label">°C</span></div><div class="memory-data" style="font-family:monospace;font-size:11px">if temp &gt; ${v}: fan = ON</div><div class="hardware-tags"><span>Fan ${cool?'ON':'OFF'}</span><span>Saved in flash</span></div></div></div>${opts([['25','Firmware A: 25°C'],['30','Firmware B: 30°C']],v)}`)+effect(`The hardware stays the same. <strong>A different rule turns the fan ${cool?'on':'off'}.</strong>`)}
if(current==='connectivity'){const data={wifi:{name:'Wi-Fi',hop:'Router',ic:'wifi-high',end:'Internet',endic:'cloud',fit:'Camera, home sensor',energy:'Often higher radio power',path:'A local access point links the device to a network.'},ble:{name:'Bluetooth Low Energy (BLE)',hop:'Phone',ic:'device-mobile',end:'App',endic:'app-window',fit:'Wearable, beacon',energy:'Low power options',path:'The phone receives the reading. Internet access is optional.'},zigbee:{name:'Zigbee',hop:'Coordinator',ic:'graph',end:'Home hub',endic:'house',fit:'Lights, home sensors',energy:'Low power end devices',path:'The local mesh links devices. A gateway can bridge to other networks.'},lora:{name:'LoRaWAN',hop:'Gateway',ic:'broadcast',end:'Server',endic:'cloud',fit:'Small field readings',energy:'Low power, small messages',path:'A gateway forwards messages to a network server.'},cell:{name:'Cellular',hop:'Cell tower',ic:'cell-tower',end:'Internet',endic:'cloud',fit:'Trackers, remote sites',energy:'Depends on cellular type',path:'An operator network carries the data. Coverage and a service plan matter.'},ethernet:{name:'Ethernet',hop:'Switch',ic:'plugs-connected',end:'Local server',endic:'desktop',fit:'Fixed devices',energy:'Cable carries data',path:'A wired link connects the device to the LAN.'}}[v];html=stage(`<div class="network-scene">${node('Sensor','thermometer-simple',data.name)}${link(true,'24°')}${node(data.hop,data.ic)}${link(true)}${node(data.end,data.endic,'Network route')}</div><div class="network-metrics"><div><b>${data.fit}</b><span>TYPICAL USE</span></div><div><b>${data.energy}</b><span>DESIGN TRADE-OFF</span></div></div>${opts([['wifi','Wi-Fi'],['ble','Bluetooth LE'],['zigbee','Zigbee'],['lora','LoRaWAN'],['cell','Cellular'],['ethernet','Ethernet']],v)}`)+effect(`<strong>${data.name}.</strong> ${data.path}`)}
if(current==='range'){html=stage(`<div class="network-scene">${node('Sensor','bluetooth','BLE link')}${link(!state.wall,'24°')}${state.wall?node('Wall','wall','Obstacle','amber'):node('Open space','wind','Clear path')}${link(!state.wall)}${node('Phone','device-mobile',state.wall?'Reading missed':'Reading received',state.wall?'off':'')}</div><div class="dots">${Array.from({length:5},(_,i)=>`<span class="dot ${i<(state.wall?1:5)?'on':''}"></span>`).join('')}</div><div class="map-caption">Illustrative signal quality</div>${action('wall',state.wall?'Remove the wall':'Add a thick wall','wall')}`)+effect(state.wall?'In this setup the link fails. <strong>Obstacles weaken radio signals.</strong>':'The clear path lets the phone receive the reading.',state.wall)}
if(current==='mesh'){html=stage(`<div class="network-scene">${node('Sensor','thermometer-simple','Battery end device')}${link(state.relay)}${node(state.relay?'Powered relay':'Blocked path',state.relay?'plugs':'wall',state.relay?'Zigbee router':'Direct link lost',state.relay?'':'amber')}${link(state.relay)}${node('Coordinator','graph',state.relay?'Reading received':'No reading',state.relay?'':'off')}</div>${action('relay',state.relay?'Remove the relay':'Add a powered relay','plus')}`)+effect(state.relay?'The powered router forwards the message. <strong>The sensor has another path.</strong>':'A mesh can use another route, if a suitable relay is within reach.',!state.relay)}
if(current==='bandwidth'){const video=v==='video';html=stage(`<div class="network-scene">${node(video?'Video':'Reading',video?'video-camera':'thermometer-simple',video?'Continuous frames':'24.8°C')}${link(!video)}${node('LoRaWAN','broadcast','Small messages')}${link(!video)}${node('Server','cloud',video?'Not suitable':'Reading received',video?'off':'')}</div><div class="work-queue">${Array.from({length:8},(_,i)=>`<div class="task ${video?'':'done'}">${icon(video?'image':'check')}</div>`).join('')}</div>${opts([['reading','Send a reading','thermometer-simple'],['video','Stream video','video-camera']],v)}`)+effect(video?'Continuous video needs a much higher data rate. <strong>Try Wi-Fi or Ethernet instead.</strong>':'A small, occasional reading fits LoRaWAN’s design.',video)}
if(current==='poe'){const power=v==='poe';html=stage(`<div class="network-scene">${node(power?'PoE switch':'Ethernet switch','plugs-connected','Source')}${link(true,power?'data + power':'data')}${node('Camera','video-camera',power?'Powered & online':'Needs separate power',power?'':'off')}</div><div class="network-metrics"><div><b>${icon('arrows-left-right')} Data link</b><span>CONNECTED</span></div><div><b>${icon('lightning')} Power</b><span>${power?'SAME CABLE':'SEPARATE ADAPTER NEEDED'}</span></div></div>${opts([['ethernet','Ethernet only'],['poe','Compatible PoE']],v)}`)+effect(power?'Compatible PoE equipment supplies <strong>data and power on one cable.</strong>':'An ordinary Ethernet link carries data. <strong>It does not automatically power the camera.</strong>')}
if(current==='edge'){const local=v==='edge',works=local||state.online;html=stage(`<div class="network-scene">${node('Door sensor','door','Open signal')}${link(works,'signal')}${node(local?'Local controller':'Cloud service',local?'cpu':'cloud',state.online?'Internet available':'Internet disconnected',!local&&!state.online?'off':'')}${link(works,'open')}${node('Lock','lock-open',works?'Responds':'Waiting for cloud',works?'':'off')}</div>${opts([['edge','Decide locally','cpu'],['cloud','Ask the cloud','cloud']],v)}${action('internet',state.online?'Disconnect internet':'Reconnect internet',state.online?'wifi-slash':'wifi-high')}`)+effect(works?local?'The local controller makes the decision. <strong>Internet is optional for this control loop.</strong>':'The cloud response arrives over the internet.':'The remote decision cannot return. <strong>This design needs an offline fallback.</strong>',!works)}
if(current==='updates'){html=stage(`<div class="flow">${node('Device','video-camera',state.updated?'Firmware v2':'Firmware v1')}${link(false)}${node(state.updated?'Known flaw patched':'Known weakness',state.updated?'shield-check':'shield-warning',state.updated?'Update installed':'Update available',state.updated?'':'amber')}</div><div class="dots">${Array.from({length:5},(_,i)=>`<span class="dot ${state.updated||i<1?'on':''}"></span>`).join('')}</div>${action('update',state.updated?'Restore demo v1':'Install security update','download-simple')}<p class="note-small">Conceptual device. A patch does not guarantee complete security.</p>`)+effect(state.updated?'The update fixes this known weakness. <strong>Keep checking for supported updates.</strong>':'A fix is available. <strong>The device stays vulnerable until it installs the patch.</strong>',!state.updated)}
if(current==='cls'){const level=Number(v),labels=['Security baseline','International standard requirements','Lifecycle review & binary analysis','Penetration testing'];html=stage(`<div class="stars" aria-label="${level} asterisks">${'*'.repeat(level)}</div><div class="security-stack">${labels.map((name,i)=>`<div class="security-tier ${i<level?'active':''}"><span>${icon(i<level?'check-circle':'circle')} ${name}</span><span>Tier ${i+1}</span></div>`).join('')}</div>${opts([['1','Level 1'],['2','Level 2'],['3','Level 3'],['4','Level 4']],v)}<p class="note-small">Illustrative label, not a product certification.</p>`)+effect(`<strong>Level ${level}</strong> includes assessment tiers 1${level>1?'–'+level:''}. More assessment still does not guarantee perfect security.`)}
if(current==='quiz')html=renderQuiz();
$('experiment').innerHTML=html;const p=$('experiment').querySelector('.primary');if(p&&current==='cpu'&&state.busy)p.disabled=true;
}
const questions=[
{q:'The power goes off. Where does an unsaved sensor reading disappear?',options:['RAM','ROM','Flash'],answer:0,why:'Ordinary RAM needs power to retain working data. ROM and flash keep their contents.',icon:'power',demo:'memory'},
{q:'A 5,000 mAh battery supplies 100 mA. What is the simple runtime estimate?',options:['5 hours','50 hours','500 hours'],answer:1,why:'5,000 ÷ 100 = 50 hours, under the simple constant-current assumptions.',icon:'battery-high',demo:'battery'},
{q:'A battery soil sensor makes one reading a minute. Which is the usual starting point?',options:['MCU','Desktop computer','Cloud server only'],answer:0,why:'An MCU usually offers enough control with low power. The exact radio and sensing design still matter.',icon:'plant',demo:'sleep'},
{q:'Which connection fits continuous video better than LoRaWAN?',options:['Wi-Fi or Ethernet','LoRaWAN','A GPIO pin alone'],answer:0,why:'Video needs a much higher data rate than occasional sensor messages.',icon:'video-camera',demo:'bandwidth'},
{q:'A smart door must respond during an internet outage. Where should its fallback decision run?',options:['Only in the cloud','Locally','Inside the battery'],answer:1,why:'A local control loop can work while the internet is down, if local power and components still work.',icon:'door',demo:'edge'},
{q:'How do CPU, MCU and SBC relate?',options:['Both MCU and SBC contain CPU cores','CPU and MCU are both board types','An SBC has no CPU'],answer:0,why:'CPU is the instruction engine; an MCU integrates functions on a chip; an SBC is a complete board.',icon:'circuitry',demo:'hardware'},
{q:'Twelve readings need twelve slots. What helps an eight-slot buffer?',options:['More clock speed only','More RAM','More ROM boot code'],answer:1,why:'The immediate limit is working-memory capacity, not processing speed.',icon:'memory',demo:'ram'},
{q:'Fifty small campus sensors report to one Linux dashboard. What is a sensible design?',options:['MCU nodes + SBC gateway','An SBC has to be in every sensor','No local network'],answer:0,why:'MCUs can handle simple sensing; an SBC gateway can aggregate readings and run the dashboard.',icon:'graph',demo:'hardware'},
{q:'Which memory normally stores firmware you can update?',options:['Flash','Volatile RAM only','Fixed mask ROM'],answer:0,why:'Flash retains contents without power and can be rewritten with new firmware.',icon:'download-simple',demo:'firmware'},
{q:'Does a four-star CLS label mean a device cannot be attacked?',options:['Yes, always','No, it describes assessment','Only if it uses Wi-Fi'],answer:1,why:'The label records completed assessment tiers. Secure configuration and ongoing updates still matter.',icon:'shield-check',demo:'cls'}
];
function renderQuiz(){if(state.index>=questions.length)return stage(`<div class="quiz-scene">${icon('check-circle')}<h3>${state.score} / ${questions.length}</h3><p class="small-label">${state.score>=8?'You can apply the key concepts.':'Replay a demo, then try again.'}</p>${action('restartquiz','Try again','arrow-counter-clockwise')}</div>`,'PRACTICE COMPLETE')+effect('Explain one example to a classmate. <strong>What changed, and why?</strong>');const q=questions[state.index],answered=state.answer!==null,correct=state.answer===q.answer;return stage(`<div class="quiz-scene"><div class="quiz-counter">QUESTION ${state.index+1} / ${questions.length}</div>${icon(q.icon)}<h3>${q.q}</h3><div class="quiz-options">${q.options.map((s,i)=>`<button class="choice ${state.answer===i?'selected':''}" data-action="answer" data-value="${i}" ${answered?'disabled':''}>${s}</button>`).join('')}</div>${answered?`<div class="quiz-result ${correct?'':'wrong'}">${icon(correct?'check-circle':'arrow-counter-clockwise')} <strong>${correct?'That’s right.':'Try the idea again.'}</strong> ${q.why}</div><div class="action-row"><button class="primary" data-action="nextquestion">${state.index===questions.length-1?'See result':'Next question'} ${icon('arrow-right')}</button><button class="text-button" data-action="replaydemo" data-value="${q.demo}">Replay the demo</button></div>`:'<p class="hint">Choose once. See the reason.</p>'}</div>`,'CHECK YOUR UNDERSTANDING')+effect('Apply the idea to a new situation. No calculator needed except the battery question.')}
function perform(a,value){if(a==='choose'){timers.forEach(clearInterval);timers=[];state.value=value;if(current==='cpu'){state.processed=0;state.busy=false}}else if(a==='process'){if(state.busy)return;state.processed=0;state.busy=true;const timer=setInterval(()=>{state.processed=Math.min(8,state.processed+Number(state.value));if(state.processed===8){state.busy=false;clearInterval(timer)}draw()},450);timers.push(timer)}else if(a==='power')state.on=!state.on;else if(a==='readings')state.count=12;else if(a==='press')state.on=!state.on;else if(a==='wall')state.wall=!state.wall;else if(a==='relay')state.relay=!state.relay;else if(a==='internet')state.online=!state.online;else if(a==='update')state.updated=!state.updated;else if(a==='answer'){if(state.answer!==null)return;state.answer=Number(value);if(state.answer===questions[state.index].answer)state.score++}else if(a==='nextquestion'){state.index++;state.answer=null}else if(a==='restartquiz')init('quiz');else if(a==='replaydemo'){navigate(value);return}mark();draw()}
$('experiment').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)perform(b.dataset.action,b.dataset.value)});$('categories').addEventListener('click',e=>{const b=e.target.closest('[data-group]');if(b)navigate(lessons.find(l=>l.group===b.dataset.group).id)});$('lessons').addEventListener('click',e=>{const b=e.target.closest('[data-lesson]');if(b)navigate(b.dataset.lesson)});$('reset').onclick=()=>navigate(current);$('next').onclick=()=>navigate(lessons[(lessons.findIndex(l=>l.id===current)+1)%lessons.length].id);window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));document.querySelector('.brand').onclick=e=>{e.preventDefault();navigate('speed')};
const facts=[
{slide:'5, 19',title:'mAh measures charge, not energy',text:'Use mAh for electric charge capacity and Wh for energy. Runtime = mAh ÷ mA is a simple constant-current estimate. Comparing batteries at different voltages requires energy, not mAh alone. “Real life is always less” is too absolute: the result depends on the assumptions and rating conditions.',link:'https://data.energizer.com/pdfs/non-rechargeable_faq.pdf',source:'Energizer battery FAQ'},
{slide:'10, 11, 13',title:'Program memory can be external',text:'CPU, RAM and peripherals commonly share an MCU chip. Flash is not always on the chip: RP2040 has internal SRAM and boot ROM but uses external flash for program storage. Treat “RAM, ROM and all peripherals on one chip” as a simplified picture, not a universal rule.',link:'https://www.raspberrypi.com/documentation/microcontrollers/microcontroller-chips.html',source:'Raspberry Pi microcontroller documentation'},
{slide:'11',title:'MCUs are not usually only 8/16-bit',text:'8-bit and 16-bit MCU families exist, but modern IoT MCUs are also commonly 32-bit. RP2040 and many Cortex-M parts are concrete 32-bit examples. “MCU below 500 MHz / microprocessor above 1 GHz” is a tendency, not a classification rule. Power, cost and performance depend on the specific device.',link:'https://www.raspberrypi.com/products/rp2040/specifications/',source:'RP2040 specifications'},
{slide:'11',title:'Harvard vs Von Neumann is not MCU vs CPU',text:'The split is not universal. Cortex-M0 uses a Von Neumann bus architecture while Cortex-M3 uses Harvard-style buses; both are MCU CPU cores. Many application processors use separate instruction/data caches. Explain memory and bus organization per architecture.',link:'https://armkeil.blob.core.windows.net/developer/Files/pdf/ebook/arm-fundamentals-soc.pdf',source:'Arm fundamentals of SoC design'},
{slide:'12',title:'Cortex-M and phone application processors differ',text:'Cortex-M targets embedded control and low-power MCU tasks. Smartphone main application processors usually use Cortex-A/Cortex-X or other application-class cores. A phone can contain auxiliary Cortex-M controllers, so “Cortex-M in phones” needs that context. The claim about “most commercial IoT devices” needs evidence.',link:'https://www.arm.com/architecture/cpu',source:'Arm architecture profiles'},
{slide:'12',title:'Arduino is not a Wi-Fi SoC',text:'Arduino is a hardware/software platform. The classic Uno Rev3 uses an ATmega328P MCU and does not include Wi-Fi. ESP32 is an Espressif SoC family; many variants provide Wi-Fi/Bluetooth and can be programmed using the Arduino framework. These names should not be used interchangeably.',link:'https://docs.arduino.cc/hardware/uno-rev3/',source:'Arduino Uno Rev3 documentation'},
{slide:'12',title:'FPGA and ASIC are different implementation choices',text:'An FPGA uses programmable logic. An ASIC is a custom integrated circuit. They are not MCU families. Moving an FPGA design to an ASIC requires engineering and verification; it is not simply an automatic next step.',link:'https://www.amd.com/content/dam/amd/en/documents/products/adaptive-socs-and-fpgas/spartan-ultrascale-plus/unlocking-innovation-cop-fpga-adaptive-socs-ebook.pdf',source:'AMD: what is an FPGA?'},
{slide:'13',title:'ROM and flash need separate explanations',text:'The image calls firmware software stored in ROM. Fixed ROM is not usually rewritable in service. Modern updateable firmware often lives in flash, which is nonvolatile and rewritable. RAM may hold code while running, but unsaved working data normally disappears when power is removed.',link:'https://docs.arduino.cc/learn/programming/memory-guide/',source:'Arduino memory guide'},
{slide:'15',title:'The nested MCU/SBC image is misleading',text:'The diagram suggests an SBC is an MCU with an improved CPU and extra connectors. These categories describe different levels: an MCU is a chip, an SBC is a board. Many SBCs use an application processor SoC, external RAM and storage interfaces. A CPU is a core/component within either design.',link:'https://www.raspberrypi.com/products/raspberry-pi-5/',source:'Raspberry Pi 5 board specifications'},
{slide:'15, 19',title:'MCUs can run operating systems and multiple tasks',text:'Many MCUs run a firmware loop, but others run an RTOS or interpreter and multiple tasks. SBCs often run Linux but can run other software. Use the application and resource needs to choose hardware; “MCU = one program, SBC = OS” is an introductory tendency, not an absolute distinction.',link:'https://docs.espressif.com/projects/esp-idf/en/stable/esp32/api-reference/system/freertos_idf.html',source:'Espressif FreeRTOS documentation'},
{slide:'17',title:'CLS was not formerly an IMDA scheme',text:'CSA launched CLS in 2020. IMDA residential gateway requirements and its IoT Cyber Security Guide are related but separate. The slide’s claim that CLS was previously known as an IMDA Standard Cybersecurity Labelling Scheme is unsupported and should be removed.',link:'https://www.csa.gov.sg/our-programmes/certification-and-labelling-schemes/cybersecurity-labelling-scheme/updates/',source:'CSA scheme launch and updates'},
{slide:'17, 19',title:'The router transition is supported, with timing context',text:'CSA’s 2 March 2026 release states that residential routers sold in Singapore must meet Level 1 requirements and that Level 2 requirements are expected to come into force by end-2027. Describe this as the announced transition, not a current Level 2 requirement. Verify again before teaching after that date.',link:'https://www.csa.gov.sg/news-events/press-releases/government-to-raise-cybersecurity-labelling-requirements-for-residential-routers/',source:'CSA router requirements announcement'},
{slide:'6, 7',title:'The arithmetic is correct under the stated assumptions',text:'6 × 30 × 24 = 4,320 hours. 1,000 mAh ÷ 4,320 h ≈ 0.231 mA. The second example gives 5,000 ÷ 100 = 50 h. Treat the TraceTogether capacity and six-month duration as the supplied exercise assumptions, not independently verified product specifications.',link:null},
{slide:'4',title:'PoE requires compatible power hardware',text:'The Raspberry Pi 5 example is valid only with a separate compatible PoE+ HAT and a suitable PoE supply. Ethernet alone does not provide PoE to a device. A power adapter is still required when using ordinary Ethernet.',link:'https://www.raspberrypi.com/products/raspberry-pi-5/',source:'Official Raspberry Pi 5 specifications'}
];
function showNotes(){$('notes-body').innerHTML=`<div class="teacher-activity">${icon('student')}<div><strong>Predict → click → explain.</strong><br>Ask for a prediction first. Use one demo, then one related quiz item. Compare exit-ticket answers before and after; the site itself does not measure learning improvement.</div></div><h3 style="font-size:14px">Deck corrections & clarifications</h3>${facts.map(f=>`<article class="fact-note"><h3>Slide ${f.slide} · ${f.title}</h3><p>${f.text}</p>${f.link?`<a href="${f.link}" target="_blank" rel="noopener">${f.source} ${icon('arrow-up-right')}</a>`:''}</article>`).join('')}<article class="fact-note"><h3>Real examples & network references</h3><p>The Raspberry Pi 5 and RP2040 photographs are from Raspberry Pi. The wearable and plant pot are generated representative illustrations. They are not product photos or hardware specifications.</p><p>${[['https://www.raspberrypi.com/products/raspberry-pi-5/','Raspberry Pi 5'],['https://www.raspberrypi.com/products/raspberry-pi-pico/','Pico / RP2040'],['https://www.espressif.com/en/products/socs/esp32','Espressif ESP32'],['https://www.bluetooth.com/learn-about-bluetooth/key-attributes/range/','Bluetooth range'],['https://csa-iot.org/all-solutions/zigbee/','Zigbee'],['https://lora-alliance.org/lorawan-for-developers/','LoRaWAN'],['https://www.csa.gov.sg/our-programmes/certification-and-labelling-schemes/cybersecurity-labelling-scheme/for-manufacturers/','CLS assessment tiers']].map(([u,t])=>`<a href="${u}" target="_blank" rel="noopener">${t}</a>`).join(' · ')}</p></article><article class="fact-note"><h3>Simulation assumptions</h3><p>Speed demo: a 10 Wh battery; one task per second; low speed uses 20 mW for 4 ms and high speed 300 mW for 1 ms; sleep power is 2.72 mW. Average power is 2.789 mW (about 149 days) and 3.017 mW (about 138 days). Sleep demo: 20 mA active, 0.02 mA asleep, one active second per minute, 1,000 mAh battery. Network links and CPU animations are conceptual rather than real-time measurements.</p></article>`;$('notes').showModal()}
$('notes-open').onclick=showNotes;$('sources-open').onclick=showNotes;$('notes-close').onclick=()=>$('notes').close();$('notes').addEventListener('click',e=>{if(e.target===$('notes')){const r=$('notes').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('notes').close()}});updateProgress();navigate(location.hash.slice(1));
